/**
 * Review and approval of a release inside Salesforce:
 * view the pull request's files and diffs, the code scan and the validation, then
 * approve (merge and deploy), reject, re-run the checks, or bypass a failed scan.
 *
 * Approve and reject need the Release Relay Approver (or Admin) permission; bypassing a scan
 * needs Release Relay Admin and a reason. Releases are read-only to users (OWD Read),
 * so the updates run in an elevated inner class after these checks.
 */
public with sharing class RlyReviewController {

    private static final Set<String> CHECK_OK = new Set<String>{ 'Passed', 'Skipped', 'Bypassed', 'Not configured' };
    private static final Set<String> RERUN_FROM = new Set<String>{ 'PR open', 'Checks failed', 'Ready for approval', 'Rejected' };

    public class Review {
        @AuraEnabled public RLY_Release__c request;
        @AuraEnabled public List<RLY_Release_Item__c> items;
        @AuraEnabled public List<RlyGitProvider.PrFile> files;
        @AuraEnabled public String connectionType;
        @AuraEnabled public String changeLabel;
        @AuraEnabled public String filesError;
        @AuraEnabled public String connectionLabel;
        @AuraEnabled public String repository;
        @AuraEnabled public Boolean isOwner;
        @AuraEnabled public Boolean canApprove;
        @AuraEnabled public Boolean canReject;
        @AuraEnabled public Boolean canBypass;
        @AuraEnabled public Boolean canRerun;
        @AuraEnabled public String approveBlockedReason;
        @AuraEnabled public Boolean canEdit;
        @AuraEnabled public Boolean canSyncBack;
        @AuraEnabled public String syncBackTarget;
    }

    @AuraEnabled
    public static Review getReview(Id requestId, Boolean includeFiles) {
        Data data = new Data();
        RLY_Release__c req = data.request(requestId);
        Review r = new Review();
        r.request = req;
        r.items = data.items(requestId);
        r.isOwner = req.CreatedById == UserInfo.getUserId();
        RlySettings.Connection c;
        try {
            c = RlySettings.connection(req.Connection__c);
            r.connectionLabel = c.label;
            r.repository = c.repository;
            r.connectionType = c.connectionType;
            r.changeLabel = c.changeLabel;
        } catch (Exception e) {
            r.filesError = e.getMessage();
        }
        Boolean approver = RlySettings.isApprover();
        r.approveBlockedReason = approveBlockedReason(req, c, approver);
        r.canApprove = r.approveBlockedReason == null;
        r.canReject = approver && (req.Status__c == 'Ready for approval' || req.Status__c == 'Checks failed');
        r.canBypass = RlySettings.isAdmin() && c != null && c.isGit && (req.Scan_Status__c == 'Failed' || req.Scan_Status__c == 'Error')
            && RERUN_FROM.contains(req.Status__c);
        r.canRerun = RERUN_FROM.contains(req.Status__c) && (r.isOwner || approver)
            && req.Scan_Status__c != 'Pending' && req.Validation_Status__c != 'Pending';
        Boolean writable = c != null && c.isGit && c.connectionType == RlySettings.GITHUB;
        r.canEdit = writable && r.canRerun && req.PR_Number__c != null;
        r.syncBackTarget = c == null ? null : c.environment;
        r.canSyncBack = writable && approver && req.Status__c == 'Deployed' && String.isBlank(req.Source_Environment__c)
            && String.isNotBlank(req.Target_Environment__c) && String.isNotBlank(c.environment);
        if (includeFiles == true && c != null) {
            try {
                if (c.isGit && req.PR_Number__c != null) {
                    r.files = RlyGitProvider.forConnection(c).pullFiles(req.PR_Number__c.intValue(), req.Target_Branch__c, req.Source_Branch__c);
                }
            } catch (Exception e) {
                r.filesError = e.getMessage();
            }
        }
        return r;
    }

    /**
     * Both versions of a file, for side-by-side compare and files the provider gives no diff for.
     * Returns old (target) and new (source) text; null where the file doesn't exist.
     */
    @AuraEnabled
    public static Map<String, String> getFilePair(Id requestId, String path, String baseRef, String headRef) {
        RLY_Release__c req = new Data().request(requestId);
        RlySettings.Connection c = connectionOrFail(req);
        try {
            RlyGitProvider git = RlyGitProvider.forConnection(c);
            return new Map<String, String>{
                'old' => git.getFileRaw(path, String.isBlank(baseRef) ? req.Target_Branch__c : baseRef),
                'new' => git.getFileRaw(path, String.isBlank(headRef) ? req.Source_Branch__c : headRef)
            };
        } catch (Exception e) {
            throw new AuraHandledException(e.getMessage());
        }
    }

    @AuraEnabled
    public static void approve(Id requestId, String comment) {
        Data data = new Data();
        RLY_Release__c req = data.request(requestId);
        RlySettings.Connection c = connectionOrFail(req);
        String blocked = approveBlockedReason(req, c, RlySettings.isApprover());
        if (blocked != null) {
            throw new AuraHandledException(blocked);
        }
        req.Approval_Status__c = 'Approved';
        req.Approved_By__c = UserInfo.getUserId();
        req.Approved_On__c = Datetime.now();
        req.Approval_Comment__c = comment == null ? null : comment.left(2000);
        req.Status__c = 'Approved';
        req.Error_Message__c = null;
        req.Pending_Run__c = RlyPipeline.MERGE_MODE; // the page starts it next (RlyReleaseController.startPipeline)
        data.save(req);
    }

    @AuraEnabled
    public static void reject(Id requestId, String comment) {
        if (!RlySettings.isApprover()) {
            throw new AuraHandledException('Only Release Relay approvers can reject a request.');
        }
        if (String.isBlank(comment)) {
            throw new AuraHandledException('Say what needs to change, so the developer can fix it.');
        }
        Data data = new Data();
        RLY_Release__c req = data.request(requestId);
        if (req.Status__c != 'Ready for approval' && req.Status__c != 'Checks failed') {
            throw new AuraHandledException('Only requests waiting for approval can be rejected. This one is ' + req.Status__c + '.');
        }
        req.Approval_Status__c = 'Rejected';
        req.Approved_By__c = UserInfo.getUserId();
        req.Approved_On__c = Datetime.now();
        req.Approval_Comment__c = comment.left(2000);
        req.Status__c = 'Rejected';
        data.save(req);
    }

    /** Admins only: accept a failed or errored scan, with a reason that stays on the request. */
    @AuraEnabled
    public static void bypassScan(Id requestId, String reason) {
        if (!RlySettings.isAdmin()) {
            throw new AuraHandledException('Only Release Relay admins can bypass the code scan.');
        }
        if (String.isBlank(reason) || reason.trim().length() < 10) {
            throw new AuraHandledException('Give a reason of at least 10 characters. It is kept on the request.');
        }
        Data data = new Data();
        RLY_Release__c req = data.request(requestId);
        if (req.Scan_Status__c != 'Failed' && req.Scan_Status__c != 'Error') {
            throw new AuraHandledException('Only a failed scan can be bypassed.');
        }
        if (!RERUN_FROM.contains(req.Status__c)) {
            throw new AuraHandledException('The scan can\'t be bypassed while the request is ' + req.Status__c + '.');
        }
        req.Scan_Status__c = 'Bypassed';
        req.Scan_Bypassed_By__c = UserInfo.getUserId();
        req.Scan_Bypass_Reason__c = reason.trim().left(2000);
        if (CHECK_OK.contains(req.Validation_Status__c)) {
            req.Status__c = 'Ready for approval';
            req.Approval_Status__c = 'Pending';
        }
        data.save(req);
    }

    /** Scan and validate again, for example after pushing a fix to the branch. */
    @AuraEnabled
    public static void rerunChecks(Id requestId) {
        Data data = new Data();
        RLY_Release__c req = data.request(requestId);
        Boolean owner = req.CreatedById == UserInfo.getUserId();
        if (!owner && !RlySettings.isApprover()) {
            throw new AuraHandledException('Only the person who raised the request, or an approver, can re-run the checks.');
        }
        if (!RERUN_FROM.contains(req.Status__c)) {
            throw new AuraHandledException('Checks can\'t be re-run while the request is ' + req.Status__c + '.');
        }
        Boolean scanOff = false;
        try {
            scanOff = RlySettings.connection(req.Connection__c).codeScan == false;
        } catch (Exception e) {
            scanOff = false;
        }
        req.Checks_Requested__c = Datetime.now();
        req.Scan_Status__c = scanOff ? 'Not configured' : 'Pending';
        req.Scan_Bypassed_By__c = null;
        req.Scan_Bypass_Reason__c = null;
        req.Validation_Status__c = String.isBlank(req.Target_Environment__c) ? 'Not configured' : 'Pending';
        req.Approval_Status__c = null;
        req.Status__c = 'PR open';
        req.Error_Message__c = null;
        req.Pending_Run__c = RlyPipeline.CHECK_MODE; // the page starts it next (RlyReleaseController.startPipeline)
        data.save(req);
    }

    /**
     * Saves an edited file to the release's branch as a commit, then scans and validates again.
     * Same people and statuses as Re-run checks; only files under the connection's source path.
     */
    @AuraEnabled
    public static void saveFile(Id requestId, String path, String content, String message) {
        Data data = new Data();
        RLY_Release__c req = data.request(requestId);
        RlySettings.Connection c = connectionOrFail(req);
        Boolean owner = req.CreatedById == UserInfo.getUserId();
        if (!owner && !RlySettings.isApprover()) {
            throw new AuraHandledException('Only the person who raised the request, or an approver, can edit its files.');
        }
        if (!RERUN_FROM.contains(req.Status__c) || req.PR_Number__c == null) {
            throw new AuraHandledException('Files can be edited while the ' + c.changeLabel + ' is open and not being checked. This one is ' + req.Status__c + '.');
        }
        String root = (String.isBlank(c.sourcePath) ? 'force-app/main/default' : c.sourcePath).removeEnd('/') + '/';
        if (String.isBlank(path) || !path.startsWith(root) || path.contains('..') || path.contains('\\')) {
            throw new AuraHandledException('Only files under ' + root + ' can be edited here.');
        }
        if (content == null || content.length() > 1000000) {
            throw new AuraHandledException('The file is empty or too large to save from here (1 MB at most).');
        }
        String commitMessage = String.isBlank(message)
            ? 'Edit ' + path.substringAfterLast('/') + ' in Release Relay (' + req.Name + ')'
            : message.trim().left(200) + ' (' + req.Name + ')';
        try {
            RlyGitProvider.forConnection(c).saveFile(path, req.Source_Branch__c, content, commitMessage);
        } catch (Exception e) {
            throw new AuraHandledException(e.getMessage());
        }
        rerunChecks(requestId);
    }

    /**
     * After a release is deployed to the next org, takes the same changes back to the source org:
     * opens a pull request from a copy of the target branch (for example sit) into the source org's
     * branch (the connection's environment, for example dev), which is validated and, once approved,
     * merged and deployed to the source org. The source org's branch is created from the default
     * branch the first time.
     */
    @AuraEnabled
    public static Id syncBack(Id requestId) {
        if (!RlySettings.isApprover()) {
            throw new AuraHandledException('Syncing back needs the Release Relay Approver permission set.');
        }
        Data data = new Data();
        RLY_Release__c req = data.request(requestId);
        RlySettings.Connection c = connectionOrFail(req);
        if (!(c.isGit && c.connectionType == RlySettings.GITHUB)) {
            throw new AuraHandledException('Sync back is available for GitHub connections.');
        }
        if (req.Status__c != 'Deployed' || String.isNotBlank(req.Source_Environment__c)) {
            throw new AuraHandledException('Only a deployed release (not a sync itself) can be synced back.');
        }
        String back = c.environment;
        String fromBranch = req.Target_Branch__c;
        if (String.isBlank(back) || String.isBlank(req.Target_Environment__c)) {
            throw new AuraHandledException('Set the connection\'s Environment (the source org\'s GitHub environment and branch, for example dev).');
        }
        String branch = 'hotfix/sync-' + fromBranch.toLowerCase().replaceAll('[^a-z0-9._-]', '-') + '-to-'
            + back.toLowerCase().replaceAll('[^a-z0-9._-]', '-') + '-' + req.Name.toLowerCase();
        if (data.openSyncExists(branch)) {
            throw new AuraHandledException('A sync for ' + req.Name + ' is already open.');
        }
        try {
            RlyGitProvider git = RlyGitProvider.forConnection(c);
            if (!git.branchExists(back)) {
                git.createBranch(back, String.isBlank(c.workflowRef) ? 'main' : c.workflowRef);
            }
            if (!git.branchExists(branch)) {
                git.createBranch(branch, fromBranch);
            }
        } catch (Exception e) {
            throw new AuraHandledException(e.getMessage());
        }
        RLY_Release__c sync = new RLY_Release__c(
            Title__c = ('Sync ' + fromBranch + ' back to ' + back + ' after ' + req.Name).left(200),
            Description__c = 'Takes ' + req.Name + ' (' + req.Title__c + '), now in ' + fromBranch + ', back to the ' + back + ' org.',
            Mode__c = 'Existing branch',
            Org_Label__c = fromBranch.toUpperCase(),
            Connection__c = req.Connection__c,
            Connection_Type__c = req.Connection_Type__c,
            Source_Environment__c = req.Target_Environment__c,
            Target_Environment__c = back,
            Checks_Requested__c = Datetime.now(),
            Scan_Status__c = c.codeScan == false ? 'Not configured' : 'Pending',
            Validation_Status__c = 'Pending',
            Deploy_Status__c = 'Pending',
            Pending_Run__c = RlyPipeline.RAISE_MODE,
            Source_Branch__c = branch,
            Target_Branch__c = back,
            Deletion_Count__c = 0,
            Component_Count__c = req.Component_Count__c,
            Request_Type__c = 'Manual PR',
            Status__c = 'Submitted'
        );
        data.insertRequest(sync);
        return sync.Id; // the page starts its pipeline next (RlyReleaseController.startPipeline)
    }

    /** Null when the current user may approve now, else the reason they can't. */
    @TestVisible
    private static String approveBlockedReason(RLY_Release__c req, RlySettings.Connection c, Boolean approver) {
        if (!approver) {
            return 'Approving needs the Release Relay Approver permission set.';
        }
        if (req.Status__c != 'Ready for approval') {
            return 'This request is ' + req.Status__c + ', not ready for approval.';
        }
        if (!CHECK_OK.contains(req.Scan_Status__c)) {
            return 'The code scan hasn\'t passed.';
        }
        if (!CHECK_OK.contains(req.Validation_Status__c)) {
            return 'Validation against ' + req.Target_Branch__c + ' hasn\'t passed.';
        }
        Boolean selfAllowed = c != null && c.allowSelfApproval == true;
        if (req.CreatedById == UserInfo.getUserId() && !selfAllowed) {
            return 'You raised this request, so someone else has to approve it.';
        }
        return null;
    }

    private static RlySettings.Connection connectionOrFail(RLY_Release__c req) {
        try {
            return RlySettings.connection(req.Connection__c);
        } catch (Exception e) {
            throw new AuraHandledException(e.getMessage());
        }
    }

    /** Requests are read-only to users; actions are permission-checked above, then saved here. */
    private without sharing class Data {
        public RLY_Release__c request(Id reqId) {
            List<RLY_Release__c> rows = [
                SELECT Id, Name, Title__c, Description__c, Mode__c, Request_Type__c, Org_Label__c, Connection__c, Connection_Type__c,
                       Source_Branch__c, Target_Branch__c, Target_Environment__c, Status__c, PR_Number__c, PR_URL__c,
                       Run_URL__c, Component_Count__c, Deletion_Count__c, Error_Message__c, Last_Synced__c, Checks_Requested__c,
                       Scan_Status__c, Scan_Violations__c, Scan_Blocking__c, Scan_Result__c,
                       Scan_Bypassed_By__c, Scan_Bypassed_By__r.Name, Scan_Bypass_Reason__c,
                       Validation_Status__c, Validation_Result__c,
                       Approval_Status__c, Approved_By__c, Approved_By__r.Name, Approved_On__c, Approval_Comment__c,
                       Merge_Commit__c, Deploy_Status__c, Deploy_Result__c, Source_Environment__c, Pending_Run__c,
                       CreatedById, CreatedBy.Name, CreatedDate
                FROM RLY_Release__c WHERE Id = :reqId];
            if (rows.isEmpty()) {
                throw new AuraHandledException('Request not found.');
            }
            return rows[0];
        }
        public List<RLY_Release_Item__c> items(Id reqId) {
            return [SELECT Id, Metadata_Type__c, Component_Name__c, Change_Type__c, Source__c
                    FROM RLY_Release_Item__c WHERE Release__c = :reqId ORDER BY Metadata_Type__c, Component_Name__c];
        }
        public Boolean openSyncExists(String branch) {
            return ![SELECT Id FROM RLY_Release__c WHERE Source_Branch__c = :branch
                     AND Status__c NOT IN ('Deployed', 'Closed', 'Failed', 'Merged') LIMIT 1].isEmpty();
        }
        public void insertRequest(RLY_Release__c req) {
            insert req;
        }
        /** Writes only the action fields, on a clean record (the query also carries parent names). */
        public void save(RLY_Release__c req) {
            update new RLY_Release__c(
                Id = req.Id,
                Status__c = req.Status__c,
                Error_Message__c = req.Error_Message__c,
                Checks_Requested__c = req.Checks_Requested__c,
                Scan_Status__c = req.Scan_Status__c,
                Scan_Bypassed_By__c = req.Scan_Bypassed_By__c,
                Scan_Bypass_Reason__c = req.Scan_Bypass_Reason__c,
                Validation_Status__c = req.Validation_Status__c,
                Approval_Status__c = req.Approval_Status__c,
                Approved_By__c = req.Approved_By__c,
                Approved_On__c = req.Approved_On__c,
                Approval_Comment__c = req.Approval_Comment__c,
                Pending_Run__c = req.Pending_Run__c
            );
        }
    }
}
